  'pur.st.true': { en: 'Mark the line that is truest now', ta: 'இப்போது மிக உண்மையாக இருக்கும் வரியைக் குறியுங்கள்', hi: 'वह पंक्ति चुनिए जो अभी सबसे सच है' },
