  'pur.st.share': { en: 'Decide whether Kavya reads this version', ta: 'இந்தப் பதிப்பை Kavya படிக்கலாமா என்று முடிவு செய்யுங்கள்', hi: 'तय कीजिए कि Kavya यह संस्करण पढ़ें या नहीं' },
  'pur.st.ready': { en: 'Ready for Day 90. Coach Priya will open the statement with you.', ta: 'நாள் 90-க்குத் தயார். பயிற்சியாளர் Priya உங்களுடன் அறிக்கையைத் திறந்து பார்ப்பார்.', hi: 'दिन 90 के लिए तैयार। कोच Priya आपके साथ बयान खोलेंगी।' },
  'pur.st.opens': { en: 'Coach Priya opens the statement with you at the Day-90 review.', ta: 'நாள்-90 மதிப்பாய்வில் பயிற்சியாளர் Priya உங்களுடன் அறிக்கையைத் திறந்து பார்ப்பார்.', hi: 'दिन-90 की समीक्षा में कोच Priya आपके साथ बयान खोलती हैं।' },
