  'pur.cl.eyebrow': { en: 'Contribution log', ta: 'பங்களிப்புப் பதிவு', hi: 'योगदान की डायरी' },
  'pur.cl.title': { en: '{n} times this month your work helped someone', ta: 'இந்த மாதம் உங்கள் வேலை {n} முறை ஒருவருக்கு உதவியது', hi: 'इस महीने {n} बार आपके काम से किसी की मदद हुई' },
  'pur.cl.sub': { en: 'Not achievements. Who was better off, and how.', ta: 'சாதனைகள் அல்ல. யார் நலம் பெற்றார்கள், எப்படி.', hi: 'उपलब्धियाँ नहीं। किसका भला हुआ, और कैसे।' },
