  'pur.v.good': { en: 'What you are good at', ta: 'நீங்கள் சிறப்பாகச் செய்வது', hi: 'जिसमें आप अच्छे हैं' },
  'pur.v.paid': { en: 'What you can be paid for', ta: 'உங்களுக்குப் பணம் கிடைக்கக்கூடியது', hi: 'जिसके लिए आपको पैसे मिल सकते हैं' },
  'pur.v.needs': { en: 'What the world needs', ta: 'உலகுக்குத் தேவையானது', hi: 'जिसकी दुनिया को ज़रूरत है' },
