  'pur.v.eyebrow': { en: 'Optional · career Venn', ta: 'விருப்பத்தேர்வு · தொழில் Venn', hi: 'वैकल्पिक · करियर Venn' },
  'pur.v.title': { en: 'The four-circle diagram, if it helps', ta: 'நான்கு வட்ட வரைபடம், உதவினால்', hi: 'चार घेरों वाला चित्र, अगर काम आए' },
  'pur.v.sub': { en: 'Popular in the West as “ikigai”; we keep it optional and separate. Useful for one question: where does work overlap with what you love?', ta: 'மேற்கில் “இக்கிகை” என்று பிரபலமானது; நாங்கள் இதை விருப்பத்தேர்வாகவும் தனியாகவும் வைக்கிறோம். ஒரு கேள்விக்குப் பயன்படும்: உங்கள் வேலை நீங்கள் விரும்புவதோடு எங்கே சந்திக்கிறது?', hi: 'पश्चिम में यह “इकिगाई” के नाम से मशहूर है; हम इसे वैकल्पिक और अलग रखते हैं। एक सवाल के लिए काम का: आपका काम आपकी पसंद से कहाँ मिलता है?' },
  'pur.v.show': { en: 'Show the career Venn', ta: 'தொழில் Venn-ஐக் காட்டு', hi: 'करियर Venn दिखाएँ' },
  'pur.v.private': { en: 'Private to you. It does not change your Purpose score.', ta: 'உங்களுக்கு மட்டும். இது உங்கள் நோக்கம் மதிப்பெண்ணை மாற்றாது.', hi: 'सिर्फ़ आपके लिए। इससे आपका उद्देश्य स्कोर नहीं बदलता।' },
  'pur.v.aria': { en: 'Career Venn: four overlapping circles. {list}.', ta: 'தொழில் Venn: ஒன்றின் மேல் ஒன்று படியும் நான்கு வட்டங்கள். {list}.', hi: 'करियर Venn: एक-दूसरे पर चढ़े चार घेरे। {list}।' },
  'pur.v.nothingYet': { en: 'nothing yet', ta: 'இன்னும் எதுவும் இல்லை', hi: 'अभी कुछ नहीं' },
