  'pur.v.errEmpty': { en: 'Type a few words.', ta: 'சில வார்த்தைகளைத் தட்டச்சு செய்யுங்கள்.', hi: 'कुछ शब्द लिखिए।' },
  'pur.v.errDup': { en: 'That is already in this circle.', ta: 'அது ஏற்கனவே இந்த வட்டத்தில் உள்ளது.', hi: 'यह पहले से इस घेरे में है।' },
  'pur.v.errFull': { en: 'Six per circle is plenty. Remove one first.', ta: 'ஒரு வட்டத்துக்கு ஆறு போதும். முதலில் ஒன்றை நீக்குங்கள்.', hi: 'एक घेरे में छह काफ़ी हैं। पहले एक हटाइए।' },
  'pur.v.dot': { en: 'The dot in the middle is where all four overlap. For you, today:', ta: 'நடுவில் உள்ள புள்ளிதான் நான்கும் சந்திக்கும் இடம். இன்று, உங்களுக்கு:', hi: 'बीच का बिंदु वह जगह है जहाँ चारों मिलते हैं। आज, आपके लिए:' },
  'pur.v.overlap': { en: 'Where all four overlap', ta: 'நான்கும் சந்திக்கும் இடம்', hi: 'जहाँ चारों मिलते हैं' },
  'pur.v.keep': { en: 'Keep', ta: 'வை', hi: 'रखें' },

