  'ppl.title': { en: 'The people who make it {e}', ta: 'வாழ்க்கையை {e} மனிதர்கள்', hi: 'वे लोग जो इसे {e} बनाते हैं' },
  'ppl.titleE': { en: 'yours', ta: 'உங்களுடையதாக்கும்', hi: 'आपका' },
  'ppl.c.eyebrow': { en: 'Circles · Dunbar', ta: 'வட்டங்கள் · Dunbar', hi: 'सर्कल · Dunbar' },
  'ppl.c.title': { en: 'Draw your 5 and your 15', ta: 'உங்கள் 5 பேரையும் 15 பேரையும் வரையுங்கள்', hi: 'अपने 5 और अपने 15 बनाइए' },
  'ppl.c.sub': { en: 'The five you lean on, and the fifteen you keep up with. Names only: contacts never leave your phone.', ta: 'நீங்கள் சாய்ந்துகொள்ளும் ஐவர், தொடர்பில் இருக்கும் பதினைவர். பெயர்கள் மட்டும்: தொடர்புகள் உங்கள் போனை விட்டு வெளியே போவதில்லை.', hi: 'वे पाँच जिन पर आप टिकते हैं, और वे पंद्रह जिनसे आप जुड़े रहते हैं। सिर्फ़ नाम: कॉन्टैक्ट आपके फ़ोन से बाहर नहीं जाते।' },
  'ppl.c.unseen': { en: '{n} not seen this month', ta: 'இந்த மாதம் {n} பேரைச் சந்திக்கவில்லை', hi: 'इस महीने {n} से नहीं मिले' },
  'ppl.c.aria': { en: 'Circles. Your 5: {a}. Your 15: {b}. Not seen this month: {c}.', ta: 'வட்டங்கள். உங்கள் 5: {a}. உங்கள் 15: {b}. இந்த மாதம் சந்திக்காதவர்கள்: {c}.', hi: 'सर्कल। आपके 5: {a}। आपके 15: {b}। इस महीने जिनसे नहीं मिले: {c}।' },
