  'ppl.c.highlight': { en: 'Highlight who I have not seen', ta: 'நான் சந்திக்காதவர்களைக் காட்டு', hi: 'जिनसे इस महीने मुलाक़ात नहीं हुई, उन्हें उभारें' },
  'ppl.c.everyone': { en: 'Everyone, this month.', ta: 'இந்த மாதம் எல்லோரையும் சந்தித்தீர்கள்.', hi: 'इस महीने सब से मिले।' },
