  'ppl.c.removed': { en: 'Removed {name} from your {ring}.', ta: 'உங்கள் {ring}-இலிருந்து {name} நீக்கப்பட்டார்.', hi: '{name} को आपके {ring} से हटाया गया।' },
  'ppl.c.select': { en: 'Select a name in the circles to mark them seen, move them between rings, or remove them.', ta: 'சந்தித்ததாகக் குறிக்க, வளையங்களுக்கு இடையே நகர்த்த, அல்லது நீக்க, வட்டங்களில் ஒரு பெயரைத் தேர்ந்தெடுங்கள்.', hi: 'किसी को मिला हुआ चिह्नित करने, घेरों के बीच ले जाने या हटाने के लिए सर्कल में कोई नाम चुनिए।' },
