  'body.le8.trendSr': { en: 'LE8 composite: {list}.', ta: 'LE8 கூட்டு: {list}.', hi: 'LE8 कुल: {list}।' },
  'body.le8.saved': { en: 'Saved. {name} now scores {score}.', ta: 'சேமிக்கப்பட்டது. {name} இப்போது {score}.', hi: 'सहेजा गया। {name} का स्कोर अब {score} है।' },
  'body.le8.removeReading': { en: 'Remove the reading from {d}', ta: '{d} அளவீட்டை நீக்கு', hi: '{d} की रीडिंग हटाएँ' },
  'body.le8.labNote': { en: 'From a lab report. Dr Meera checks typed values against the report at your review.', ta: 'ஆய்வக அறிக்கையிலிருந்து. மதிப்பாய்வில், தட்டச்சு செய்த மதிப்புகளை Dr Meera அறிக்கையுடன் சரிபார்ப்பார்.', hi: 'लैब रिपोर्ट से। समीक्षा में Dr Meera लिखे गए मानों को रिपोर्ट से मिलाएँगी।' },
  'body.le8.err': { en: 'Check the value: {range}.', ta: 'மதிப்பைச் சரிபாருங்கள்: {range}.', hi: 'मान जाँचिए: {range}।' },
