  'body.le8.in.activity': { en: 'Moderate or vigorous minutes, last week', ta: 'மிதமான அல்லது தீவிரமான உடற்பயிற்சி நிமிடங்கள், கடந்த வாரம்', hi: 'मध्यम या तेज़ गतिविधि के मिनट, पिछला हफ़्ता' },
  'body.le8.in.nicotine': { en: 'Cigarettes, bidis, vapes or chewing tobacco', ta: 'சிகரெட், பீடி, வேப் அல்லது மெல்லும் புகையிலை', hi: 'सिगरेट, बीड़ी, वेप या चबाने वाला तंबाकू' },
  'body.le8.in.sleep': { en: 'Average sleep a night, last week', ta: 'ஒரு இரவுக்குச் சராசரி தூக்கம், கடந்த வாரம்', hi: 'हर रात औसत नींद, पिछला हफ़्ता' },
