  'body.le8.in.lipids': { en: 'Non-HDL cholesterol, mg/dL', ta: 'Non-HDL கொலஸ்ட்ரால், mg/dL', hi: 'Non-HDL कोलेस्ट्रॉल, mg/dL' },
