  'body.le8.nic.1': { en: 'Quit more than five years ago', ta: 'ஐந்து ஆண்டுகளுக்கு முன்பே நிறுத்திவிட்டேன்', hi: 'पाँच साल से भी पहले छोड़ दिया' },
  'body.le8.nic.2': { en: 'Quit one to five years ago', ta: 'ஒன்று முதல் ஐந்து ஆண்டுகளுக்கு முன் நிறுத்தினேன்', hi: 'एक से पाँच साल पहले छोड़ा' },
  'body.le8.nic.3': { en: 'Quit within the last year', ta: 'கடந்த ஓராண்டுக்குள் நிறுத்தினேன்', hi: 'पिछले एक साल में छोड़ा' },
  'body.le8.nic.4': { en: 'I use it now', ta: 'இப்போது பயன்படுத்துகிறேன்', hi: 'अभी इस्तेमाल करता हूँ' },
