  'ease.sc.replaced': { en: 'Today’s result was replaced with your corrected answers.', ta: 'இன்றைய முடிவு, நீங்கள் திருத்திய பதில்களால் மாற்றப்பட்டது.', hi: 'आज का नतीजा आपके सुधारे हुए जवाबों से बदल दिया गया।' },
  'ease.route.PHQ-4.today': { en: 'Routed to Dr Sanjay Menon. He will call you today. If you need someone sooner, Tele-MANAS is one tap away.', ta: 'Dr Sanjay Menon-க்கு அனுப்பப்பட்டது. அவர் இன்றே உங்களை அழைப்பார். அதற்கு முன்பே யாராவது தேவைப்பட்டால், Tele-MANAS ஒரு தட்டலில் உள்ளது.', hi: 'Dr Sanjay Menon को भेजा गया। वे आज ही आपको फ़ोन करेंगे। अगर उससे पहले किसी की ज़रूरत हो, तो Tele-MANAS बस एक टैप दूर है।' },
  'ease.cr.r0w': { en: 'PHQ-4 9 or more', ta: 'PHQ-4 9 அல்லது அதற்கு மேல்', hi: 'PHQ-4 9 या ज़्यादा' },
  'ease.cr.r0t': { en: '{name} calls you the same day', ta: '{name} அதே நாளில் உங்களை அழைப்பார்', hi: '{name} उसी दिन फ़ोन करते हैं' },
  'ease.cr.r5w': { en: 'PSS-4 11 or more', ta: 'PSS-4 11 அல்லது அதற்கு மேல்', hi: 'PSS-4 11 या ज़्यादा' },
  'ease.cr.r5t': { en: 'Coach Priya is in touch this week', ta: 'பயிற்சியாளர் Priya இந்த வாரம் தொடர்புகொள்வார்', hi: 'कोच Priya इस हफ़्ते संपर्क करती हैं' },
